{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Pravastatin, a carboxylic acid-containing drug with extensive first-pass metabolism and Pgp efflux, has an absolute oral bioavailability of 18% in healthy volunteers, directly supporting a low F (<20%) for the similarly ionized, polar query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Cicaprost, a prostacyclin analogue, shows complete oral bioavailability in humans, which would support high F, but its metabolically stabilized structure and different carboxylic acid placement limit transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "FK788, a phenoxyacetic acid analogue, has 55% oral bioavailability, but its lipophilic carbamate and lack of the query's long hydroxylated side chain make it less representative of the query's absorption and first-pass profile.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Iloprost, another prostacyclin analogue, shows 56-63% absolute bioavailability in TAO patients, but this was measured at a very low dose (50 µg) and in a specific patient population, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the query's ionized phenoxyacetic acid, high polarity, and metabolic liability align with pravastatin's low F (~18%), while high-F prostacyclin/phenoxyacetic acid analogues are less transferable due to metabolic stabilization or structural differences.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule in the provided evidence set.",
    "All evidence molecules have low Morgan similarity (<0.31), limiting quantitative transfer.",
    "Metabolic stability and transporter interactions (Pgp/OATP) are not directly measured for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

